from typing import Dict, List, Optional, Tuple
from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def num_ways_fence(n: int, k: int) -> int:
    if n == 1:
        return k
    same, diff = 0, k
    for _ in range(1, n):
        same, diff = diff, (k - 1) * (same + diff)
    return same + diff
